<?php require '../config/database.php';include '../includes/header.php';include '../includes/sidebar.php';$q=mysqli_query($conn,"SELECT b.*,c.customer_name,c.mobile_number FROM bills b LEFT JOIN customers c ON c.id=b.customer_id ORDER BY b.id DESC");?><h1>Bill History</h1><div class="panel"><table><tr><th>Bill</th><th>Date</th><th>Customer</th><th>Total</th><th>Action</th></tr><?php while($r=mysqli_fetch_assoc($q)){?><tr><td><?=$r['bill_number']?></td><td><?=$r['created_at']?></td><td><?=htmlspecialchars($r['customer_name']??'-')?></td><td>₹<?=$r['grand_total']?></td><td><a class="btn" href="../billing/receipt.php?id=<?=$r['id']?>">View / Print</a></td></tr><?php }?></table></div><?php include '../includes/footer.php';?>